scattered_test = [
    (0, 0, 9), (0, 1, 5), (0, 2, 3), (0, 3, 4),
    (1, 11, 8),
    (3, 3, 9),
    (5, 13, 6),
    (9, 7, 1),
    (11, 13, 2),
    (13, 4, 7)
]

patterns = {
    'left': [2, 1, 3, 8],
    'right': [4, 5, 6, 7],
}

output = [[0] * 18 for _ in range(17)]

def get_pattern_and_index(val):
    for name, pat in patterns.items():
        if val in pat:
            return name, pat, pat.index(val)
    return None, None, None

# Row 16 (base row)
for c in range(4):
    output[16][c] = [2, 1, 3, 8][c]
for c in range(14, 18):
    output[16][c] = [4, 5, 6, 7][c-14]

# Process each row with scattered cells
for r, c, val in scattered_test:
    pat_name, pat, idx = get_pattern_and_index(val)

    if pat_name is None:
        # Unknown pattern value - maybe means use a special pattern
        # or means "full"
        if r == 0:
            # Row 0: [9,5,3,4] - this is a custom pattern
            output[r][0:4] = [9, 5, 3, 4]
        # For row 3, value 9 - unknown
    else:
        # Normal pattern - place starting at determined column
        start_col = c - idx
        for i, pval in enumerate(pat):
            col = start_col + i
            if col < 18:
                output[r][col] = pval

# Handle row 3 special case (value 9 is unknown)
if 3 in [r for r, c, v in scattered_test]:
    # Row 3 has scattered[3]=9 at col 3
    # 9 is unknown - maybe treat as pattern
    output[3][0:4] = [9, 5, 3, 4]

# Fill output row 3  
output[3] = output[3]  # already has [2,1,3,8] from processing

print("Final output:")
for r, row in enumerate(output):
    print(f"Row {r}: {row}")

# Verify
print("\nVerification:")
for r, c, val in scattered_test:
    print(f"Scattered({r},{c})={val}, output[{r}][{c}]={output[r][c]}")

